update public.spec_templates set form_contract=jsonb_set(form_contract,'{helpers}', coalesce(form_contract->'helpers','{}'::jsonb) || '{"bearing_system": "Sellados: rodamientos de cartucho, se cambian enteros. Bolas sueltas: bolitas con conos y tazas, se ajustan y se engrasan.", "center_to_flange_left_mm": "Desde el centro de la maza hasta el plano donde están los hoyos del lado izquierdo. Si el fabricante mide desde el apoyo exterior, convierte la medida antes de escribirla.", "center_to_flange_right_mm": "Desde el centro de la maza hasta el plano donde están los hoyos del lado derecho, medido igual que el lado izquierdo.", "flange_pcd_left_mm": "Diámetro del círculo que forman los hoyos del lado izquierdo. Se mide desde el centro de un hoyo hasta el centro del hoyo opuesto. En catálogos puede aparecer como PCD.", "flange_pcd_right_mm": "Diámetro del círculo que forman los hoyos del lado derecho. Se mide desde el centro de un hoyo hasta el centro del hoyo opuesto. En catálogos puede aparecer como PCD.", "hub_axle_diameter_datum": "Indica en qué parte se midió: en la zona que entra al cuadro o la horquilla, dentro de la maza u otro punto publicado por el fabricante. El perno fino del cierre rápido no es el diámetro del eje.", "hub_axle_diameter_mm": "Grosor del eje en el punto que indicaste arriba. Cierre rápido: 9 o 10 mm. Pasante: 12 o 15 mm.", "hub_axle_mount_kind": "Cierre rápido: eje hueco con palanca (9 o 10 mm). Eje pasante: eje grueso de 12 o 15 mm que se enrosca al cuadro. Con tuercas: eje macizo con una tuerca a cada lado.", "hub_drive_receiver_kind": "Cómo se instala el piñón en esta maza trasera: sobre un núcleo estriado, en una rosca o mediante el sistema específico del fabricante.", "hub_drive_receiver_present": "Sólo para mazas traseras. Sí si trae núcleo para cassette, hilo para piñón roscado u otro montaje documentado para el piñón.", "hub_drive_receiver_reference": "Nombre exacto publicado por el fabricante, por ejemplo HG 8-11v, Micro Spline, XD o la medida de la rosca.", "hub_flange_to_flange_mm": "Distancia entre los dos planos donde están los hoyos de los rayos. Debe coincidir con la suma de las dos distancias medidas desde el centro.", "hub_old_mm": "Ancho exterior de la maza, medido entre las dos caras que apoyan en el cuadro o la horquilla. En catálogos aparece como OLD. Valores comunes: 100 mm delante; 135 mm atrás con cierre rápido; 142 o 148 mm con eje pasante.", "hub_package_piece_count": "Cuántas mazas trae el juego (normalmente dos: delantera y trasera). Confírmalo con la fuente, no por el título.", "hub_package_pieces": "Sólo lo que viene en la caja: una fila por maza. No es la lista de variantes del fabricante ni una rueda armada.", "hub_package_position": "Qué viene en la caja: una maza delantera, una trasera, o el juego de las dos. Si es el juego, cada maza va en su propia fila más abajo y no se llena un solo ancho ni una sola perforación.", "hub_rotor_mount_present": "Sí si la maza trae una fijación para disco de freno. No si sólo sirve para freno de llanta.", "hub_spoke_head_interface": "Con codo es el rayo tradicional: la cabeza doblada entra por un hoyo lateral de la maza. Recto entra sin codo. En fichas del fabricante pueden aparecer como J-bend y straight pull.", "hub_supplied_thru_axle_reference": "El código del eje que viene. Su rosca y su largo son del eje y del cuadro, no de la maza.", "hub_thru_axle_supplied": "Sí sólo si el eje pasante viene en la caja.", "rotor_mount_type": "6 pernos: el disco se atornilla con seis pernos. Center Lock: el disco entra en una estría y se asegura con un anillo.", "spec_evidence_source": "Pega el link de la página del fabricante, o escribe «manual» o «caja» si lo leíste ahí. Sin fuente, los demás datos quedan como no confirmados.", "spoke_hole_count": "Cantidad total de rayos que lleva la maza. Cuenta los hoyos de ambos lados: una maza de 32H tiene 32 en total, normalmente 16 por lado.", "spoke_hole_diameter_mm": "Diámetro de un hoyo lateral por donde entra el rayo. Valores comunes: 2,5 o 2,6 mm."}'::jsonb), updated_at=now() where tenant_id is null and key='hub' and (form_contract->'helpers') is distinct from (coalesce(form_contract->'helpers','{}'::jsonb) || '{"bearing_system": "Sellados: rodamientos de cartucho, se cambian enteros. Bolas sueltas: bolitas con conos y tazas, se ajustan y se engrasan.", "center_to_flange_left_mm": "Desde el centro de la maza hasta el plano donde están los hoyos del lado izquierdo. Si el fabricante mide desde el apoyo exterior, convierte la medida antes de escribirla.", "center_to_flange_right_mm": "Desde el centro de la maza hasta el plano donde están los hoyos del lado derecho, medido igual que el lado izquierdo.", "flange_pcd_left_mm": "Diámetro del círculo que forman los hoyos del lado izquierdo. Se mide desde el centro de un hoyo hasta el centro del hoyo opuesto. En catálogos puede aparecer como PCD.", "flange_pcd_right_mm": "Diámetro del círculo que forman los hoyos del lado derecho. Se mide desde el centro de un hoyo hasta el centro del hoyo opuesto. En catálogos puede aparecer como PCD.", "hub_axle_diameter_datum": "Indica en qué parte se midió: en la zona que entra al cuadro o la horquilla, dentro de la maza u otro punto publicado por el fabricante. El perno fino del cierre rápido no es el diámetro del eje.", "hub_axle_diameter_mm": "Grosor del eje en el punto que indicaste arriba. Cierre rápido: 9 o 10 mm. Pasante: 12 o 15 mm.", "hub_axle_mount_kind": "Cierre rápido: eje hueco con palanca (9 o 10 mm). Eje pasante: eje grueso de 12 o 15 mm que se enrosca al cuadro. Con tuercas: eje macizo con una tuerca a cada lado.", "hub_drive_receiver_kind": "Cómo se instala el piñón en esta maza trasera: sobre un núcleo estriado, en una rosca o mediante el sistema específico del fabricante.", "hub_drive_receiver_present": "Sólo para mazas traseras. Sí si trae núcleo para cassette, hilo para piñón roscado u otro montaje documentado para el piñón.", "hub_drive_receiver_reference": "Nombre exacto publicado por el fabricante, por ejemplo HG 8-11v, Micro Spline, XD o la medida de la rosca.", "hub_flange_to_flange_mm": "Distancia entre los dos planos donde están los hoyos de los rayos. Debe coincidir con la suma de las dos distancias medidas desde el centro.", "hub_old_mm": "Ancho exterior de la maza, medido entre las dos caras que apoyan en el cuadro o la horquilla. En catálogos aparece como OLD. Valores comunes: 100 mm delante; 135 mm atrás con cierre rápido; 142 o 148 mm con eje pasante.", "hub_package_piece_count": "Cuántas mazas trae el juego (normalmente dos: delantera y trasera). Confírmalo con la fuente, no por el título.", "hub_package_pieces": "Sólo lo que viene en la caja: una fila por maza. No es la lista de variantes del fabricante ni una rueda armada.", "hub_package_position": "Qué viene en la caja: una maza delantera, una trasera, o el juego de las dos. Si es el juego, cada maza va en su propia fila más abajo y no se llena un solo ancho ni una sola perforación.", "hub_rotor_mount_present": "Sí si la maza trae una fijación para disco de freno. No si sólo sirve para freno de llanta.", "hub_spoke_head_interface": "Con codo es el rayo tradicional: la cabeza doblada entra por un hoyo lateral de la maza. Recto entra sin codo. En fichas del fabricante pueden aparecer como J-bend y straight pull.", "hub_supplied_thru_axle_reference": "El código del eje que viene. Su rosca y su largo son del eje y del cuadro, no de la maza.", "hub_thru_axle_supplied": "Sí sólo si el eje pasante viene en la caja.", "rotor_mount_type": "6 pernos: el disco se atornilla con seis pernos. Center Lock: el disco entra en una estría y se asegura con un anillo.", "spec_evidence_source": "Pega el link de la página del fabricante, o escribe «manual» o «caja» si lo leíste ahí. Sin fuente, los demás datos quedan como no confirmados.", "spoke_hole_count": "Cantidad total de rayos que lleva la maza. Cuenta los hoyos de ambos lados: una maza de 32H tiene 32 en total, normalmente 16 por lado.", "spoke_hole_diameter_mm": "Diámetro de un hoyo lateral por donde entra el rayo. Valores comunes: 2,5 o 2,6 mm."}'::jsonb);
